  log('Running DOD L2...')
  dodResult = await agent(dodPrompt, { label: 'dod-l2', phase: 'Quality Gates', schema: DOD_SCHEMA })

  if (!skipLeadReview) {
    log('Running lead review...')
    reviewResult = await agent(reviewPrompt, { label: 'lead-review', phase: 'Quality Gates', schema: REVIEW_SCHEMA, agentType: 'maestro:lead-reviewer' })
  }

  if (!skipQa) {
    log('Running QA...')
    qaResult = await agent(qaPrompt, { label: 'qa', phase: 'Quality Gates', schema: QA_SCHEMA, agentType: 'maestro:qa-engineer' })
  }
}

return { dod: dodResult, review: reviewResult, qa: qaResult }
